import sys, os, json, csv, gzip, io, glob
from datetime import datetime, timedelta, timezone, date
from zoneinfo import ZoneInfo
from fractions import Fraction
from decimal import Decimal

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b.decode('utf-8-sig')


def lines_of(path):
    return [l for l in read_text(path).splitlines() if l.strip()]


def from_epoch(sec):
    return EPOCH + timedelta(seconds=int(sec))


def local_to_utc(naive, tz, fold=0):
    return naive.replace(tzinfo=tz, fold=fold).astimezone(UTC)


def std_offset(tz):
    for m in (1, 7, 4, 10):
        d = datetime(2026, m, 15, 12, tzinfo=tz)
        if not d.dst():
            return d.utcoffset()
    return datetime(2026, 1, 15, tzinfo=tz).utcoffset()


def parse_iso(s):
    s = s.strip()
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    return d.astimezone(UTC)


def norm_dir(s):
    s = str(s).strip().upper()
    return 'IN' if s in ('IN', 'CLOCK_IN', 'K', 'I') else 'OUT'


def parse_abbr(path, tz, out):
    header = None
    for line in lines_of(path):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        m, d, y = r['Date'].split('/')
        t = r['Time'].strip().upper()
        ap = None
        if t.endswith('AM') or t.endswith('PM'):
            ap = t[-2:]
            t = t[:-2].strip()
        hh, mm, ss = [int(x) for x in t.split(':')]
        if ap:
            hh = hh % 12 + (12 if ap == 'PM' else 0)
        naive = datetime(int(y), int(m), int(d), hh, mm, ss)
        z = r.get('Zone', '').strip().upper()
        fold = 1 if z.endswith('ST') else 0
        out.append((r['Record'].strip(), r['Badge'], norm_dir(r['Punch']), local_to_utc(naive, tz, fold)))


def parse_epoch(path, tz, out):
    schema = 1
    for line in lines_of(path):
        o = json.loads(line)
        if set(o.keys()) == {'schema'}:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2 or 'punch_id' in o:
            pid, emp, d, ms = o['punch_id'], o['employee'], o['direction'], o['epoch_ms']
            inst = from_epoch(int(ms) // 1000)
        else:
            pid, emp, d = o['id'], o['emp'], o['dir']
            if 'ts_ms' in o:
                inst = from_epoch(int(o['ts_ms']) // 1000)
            else:
                inst = from_epoch(int(o['ts']))
        out.append((str(pid), emp, norm_dir(d), inst))


def parse_offset(path, tz, out):
    rd = csv.DictReader(io.StringIO('\n'.join(lines_of(path))), delimiter=';')
    for r in rd:
        out.append((r['punch_id'], r['employee'], norm_dir(r['event']), parse_iso(r['timestamp'])))


def parse_legacy(path, tz, out):
    off = std_offset(tz)
    for line in lines_of(path):
        t = line[0]
        if t == 'H':
            off = std_offset(tz)
            s = line[13:18].strip()
            if len(s) == 5 and s[0] in '+-':
                v = timedelta(hours=int(s[1:3]), minutes=int(s[3:5]))
                off = v if s[0] == '+' else -v
        elif t == 'D':
            pid = line[1:9]
            badge = line[9:15].strip()
            dr = line[15]
            ts = line[16:30]
            naive = datetime.strptime(ts, '%Y%m%d%H%M%S')
            inst = (naive - off).replace(tzinfo=UTC)
            out.append((pid, 'E' + badge, norm_dir(dr), inst))


def parse_de(path, tz, out):
    rd = csv.DictReader(io.StringIO('\n'.join(lines_of(path))), delimiter='\t')
    for r in rd:
        r = {k.strip(): (v or '').strip() for k, v in r.items()}
        d, m, y = r['Datum'].split('.')
        hh, mm = r['Uhrzeit'].split(':')[:2]
        naive = datetime(int(y), int(m), int(d), int(hh), int(mm))
        fold = 1 if r.get('Zeitzone', '').upper() == 'MEZ' else 0
        out.append((r['Nr'], r['Ausweis'], norm_dir(r['Buchung']), local_to_utc(naive, tz, fold)))


def parse_local_csv(path, tz, out):
    rd = csv.DictReader(io.StringIO('\n'.join(lines_of(path))))
    for r in rd:
        naive = datetime.strptime(r['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((r['punch_ref'].strip(), r['employee_id'], norm_dir(r['direction']), local_to_utc(naive, tz, 0)))


def parse_local_jsonl(path, tz, out):
    for line in lines_of(path):
        p = json.loads(line)['punch']
        naive = datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), p['badge'], norm_dir(p['type']), local_to_utc(naive, tz, 0)))


PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_local_csv,
           'local-jsonl': parse_local_jsonl}


def read_csv(path):
    return list(csv.DictReader(io.StringIO('\n'.join(lines_of(path)))))


def main(inp, outfile):
    period = json.loads(read_text(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_iso(period['corrections_cutoff'])
    sites = {r['site'].strip(): (ZoneInfo(r['timezone'].strip()), r['format'].strip())
             for r in read_csv(os.path.join(inp, 'sites.csv'))}
    emps = {}
    for r in read_csv(os.path.join(inp, 'employees.csv')):
        emps[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    for r in read_csv(os.path.join(inp, 'rates.csv')):
        rates.setdefault(r['employee_id'].strip(), []).append(
            (date.fromisoformat(r['effective_from'].strip()), Fraction(Decimal(r['hourly_rate'].strip()))))
    for v in rates.values():
        v.sort()

    # 1 collect
    punches = {}  # (site, id) -> [emp, dir, instant]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                recs = []
                PARSERS[fmt](os.path.join(root, fn), tz, recs)
                for pid, emp, dr, inst in recs:
                    k = (site, pid)
                    ever.add(k)
                    if k not in punches:
                        punches[k] = [emp.strip(), dr, inst]

    # 2 corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for root, _, files in os.walk(cdir):
            for fn in files:
                for r in read_csv(os.path.join(root, fn)):
                    r = {k.strip(): (v or '').strip() for k, v in r.items()}
                    r['_t'] = parse_iso(r['issued_at'])
                    corr.append(r)
    corr.sort(key=lambda r: (r['_t'], r['correction_id']))
    applied = 0
    voided = set()
    for r in corr:
        if r['_t'] > cutoff:
            continue
        k = (r['site'], r['punch_id'])
        a = r['action'].lower()
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = parse_iso(r['time'])
                applied += 1
        elif a == 'add':
            if k not in ever and r['site'] in sites:
                ever.add(k)
                punches[k] = [r['employee'], norm_dir(r['type']), parse_iso(r['time'])]
                applied += 1

    # 3 duplicates
    byemp = {}
    for (site, pid), (emp, dr, inst) in punches.items():
        if emp in emps:
            byemp.setdefault(emp, []).append((inst, 0 if dr == 'OUT' else 1, site, pid, dr))
    res = {e: dict(shifts=0, paid=0, ot=0, night=0, pay=Fraction(0)) for e in emps}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    def rnd(inst, tz):
        loc = inst.astimezone(tz)
        sec = loc.minute * 60 + loc.second
        return inst + timedelta(seconds=(sec + 180) // 360 * 360 - sec)

    for emp, lst in byemp.items():
        hz = sites[emps[emp]][0] if emps[emp] in sites else UTC
        lst.sort()
        kept = []
        last = None
        wd = lambda inst: inst.astimezone(hz).date()
        for inst, o, site, pid, dr in lst:
            r = rnd(inst, sites[site][0])
            if last and last[4] == dr and (inst - last[0]).total_seconds() <= 300:
                if pstart <= wd(r) <= pend:
                    exc['duplicates_dropped'] += 1
                continue
            last = (inst, o, site, pid, dr)
            kept.append((r, dr, site))
        # 5 pair
        shifts = []
        pend_in = None

        def openshift(p):
            if pstart <= wd(p[0]) <= pend:
                exc['open_shifts'] += 1
        for r, dr, site in kept:
            if dr == 'IN':
                if pend_in:
                    openshift(pend_in)
                pend_in = (r, site)
            else:
                if pend_in and (r - pend_in[0]) <= timedelta(hours=16):
                    shifts.append((pend_in, r))
                    pend_in = None
                else:
                    if pend_in:
                        openshift(pend_in)
                        pend_in = None
                    if pstart <= wd(r) <= pend:
                        exc['orphan_outs'] += 1
        if pend_in:
            openshift(pend_in)
        # shifts in period
        sl = []
        for (i, site), o in shifts:
            w = wd(i)
            if not (pstart <= w <= pend):
                continue
            worked = max(0, int((o - i).total_seconds() // 60))
            paid = worked - 30 if worked > 360 else worked
            tz = sites[site][0]
            night = 0
            t = i
            while t < o:
                h = t.astimezone(tz).hour
                if h >= 22 or h < 6:
                    night += 1
                t += timedelta(minutes=1)
            night = min(night, paid)
            sl.append((i, w, paid, night))
        sl.sort(key=lambda x: x[0])
        daily = {}
        rows = []
        for i, w, paid, night in sl:
            used = daily.get(w, 0)
            dot = max(0, used + paid - max(used, 480))
            daily[w] = used + paid
            rows.append([i, w, paid, night, dot])
        weekly = {}
        R = res[emp]
        for i, w, paid, night, dot in rows:
            wk = w - timedelta(days=w.weekday())
            nd = paid - dot
            used = weekly.get(wk, 0)
            wot = max(0, used + nd - max(used, 2400))
            weekly[wk] = used + nd
            ot = dot + wot
            reg = paid - ot
            rate = None
            for ef, rt in rates.get(emp, []):
                if ef <= w:
                    rate = rt
            if rate is None:
                rate = Fraction(0)
            R['shifts'] += 1
            R['paid'] += paid
            R['ot'] += ot
            R['night'] += night
            R['pay'] += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60

    def cents(f):
        return (f * 100 + Fraction(1, 2)).__floor__()

    def money(c):
        return '%d.%02d' % (c // 100, c % 100)
    out = {'period': {'start': period['start'], 'end': period['end']}, 'employees': {}, 'exceptions': exc}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tc = 0
    for e in emps:
        R = res[e]
        c = cents(R['pay'])
        out['employees'][e] = dict(shifts=R['shifts'], paid_minutes=R['paid'], overtime_minutes=R['ot'],
                                   night_minutes=R['night'], gross=money(c))
        tot['shifts'] += R['shifts']; tot['paid_minutes'] += R['paid']
        tot['overtime_minutes'] += R['ot']; tot['night_minutes'] += R['night']
        tc += c
    tot['gross'] = money(tc)
    out['totals'] = tot
    with open(outfile, 'w') as f:
        json.dump(out, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
